<?php $activeMenu='router';$routerView='dhcp';require_once __DIR__.'/../includes/sidebar.php'; ?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DHCP - NetMonitor</title><link rel="stylesheet" href="../assets/css/variables.css"><link rel="stylesheet" href="../assets/css/common.css"><link rel="stylesheet" href="../assets/css/theme.css?v=1"><style>.page{margin-left:220px;padding:32px}.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.title{font-size:28px;font-weight:700}.sub{color:#66758d;margin-top:5px}.btn{border:1px solid #d7e0ec;background:#fff;border-radius:8px;padding:10px 14px;font-weight:600;cursor:pointer}.btn.primary{background:#087cff;color:#fff;border-color:#087cff}.cards{display:grid;grid-template-columns:repeat(2,1fr);gap:18px;margin-bottom:22px}.card{background:#fff;border:1px solid #dce4ef;border-radius:14px;overflow:hidden}.bar{padding:16px 20px;border-bottom:1px solid #e4e9f0;display:flex;justify-content:space-between}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:13px 15px;text-align:left;border-bottom:1px solid #edf1f6;font-size:13px}th{font-size:11px;text-transform:uppercase;color:#61718a;background:#f7f9fc}.name{font-weight:700}.badge{display:inline-block;padding:5px 9px;border-radius:99px;font-size:11px;font-weight:700}.ok{background:#dff6e9;color:#08774e}.warn{background:#fff0c7;color:#8a5a00}.muted{color:#718096}.notice{padding:14px 20px;color:#66758d}.count{font-size:12px;color:#718096}@media(max-width:800px){.page{margin-left:0;padding:20px}.head{align-items:flex-start;flex-direction:column;gap:12px}.cards{grid-template-columns:1fr}}</style></head><body><main class="page"><div class="head"><div><div class="title">DHCP</div><div class="sub">DHCP Server dan daftar lease client dari MikroTik.</div></div><button class="btn primary" id="refresh">↻ Refresh</button></div><div class="cards"><div class="card"><div class="bar"><strong>DHCP Server</strong><span class="count" id="serverCount">0 server</span></div><div class="table-wrap"><table><thead><tr><th>Nama</th><th>Interface</th><th>Address Pool</th><th>Status</th></tr></thead><tbody id="servers"><tr><td colspan="4" class="notice">Mengambil data...</td></tr></tbody></table></div></div><div class="card"><div class="bar"><strong>Lease Client</strong><span class="count" id="leaseCount">0 lease</span></div><div class="table-wrap"><table><thead><tr><th>IP</th><th>MAC Address</th><th>Hostname</th><th>Server</th><th>Status</th><th>Expires</th></tr></thead><tbody id="leases"><tr><td colspan="6" class="notice">Mengambil data...</td></tr></tbody></table></div></div></div></main><script>const servers=document.getElementById('servers'),leases=document.getElementById('leases'),serverCount=document.getElementById('serverCount'),leaseCount=document.getElementById('leaseCount'),refresh=document.getElementById('refresh');function esc(v){return String(v??'-').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}async function load(){refresh.disabled=true;try{const r=await fetch('../api/router_dhcp.php?nocache='+Date.now(),{cache:'no-store'});const d=await r.json();if(d.status!=='online')throw Error(d.message||'Router offline');serverCount.textContent=(d.servers||[]).length+' server';leaseCount.textContent=(d.leases||[]).length+' lease';servers.innerHTML=(d.servers||[]).map(x=>`<tr><td class="name">${esc(x.name)}</td><td>${esc(x.interface)}</td><td>${esc(x.address_pool)}</td><td><span class="badge ${x.disabled?'warn':'ok'}">${x.disabled?'DISABLED':'RUNNING'}</span></td></tr>`).join('')||'<tr><td colspan="4" class="notice">Tidak ada DHCP Server.</td></tr>';leases.innerHTML=(d.leases||[]).map(x=>`<tr><td class="name">${esc(x.address)}</td><td>${esc(x.mac)}</td><td>${esc(x.hostname)}</td><td>${esc(x.server)}</td><td><span class="badge ${x.disabled?'warn':'ok'}">${esc(x.status)}</span></td><td class="muted">${esc(x.expires)}</td></tr>`).join('')||'<tr><td colspan="6" class="notice">Tidak ada lease.</td></tr>'}catch(e){servers.innerHTML='<tr><td colspan="4" class="notice">Gagal mengambil data: '+esc(e.message)+'</td></tr>';leases.innerHTML='<tr><td colspan="6" class="notice">Gagal mengambil data: '+esc(e.message)+'</td></tr>'}finally{refresh.disabled=false}}refresh.onclick=load;load();setInterval(load,10000);</script><script src="../assets/js/app.js?v=6"></script></body></html>